<?php
declare(strict_types=1);
session_start();
header('X-Content-Type-Options: nosniff');
const TABLES=['personas','publicaciones','comentarios','reacciones','conexiones'];
function h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO{$p=new PDO('sqlite:'.__DIR__.'/../red.db');$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$p->exec('PRAGMA foreign_keys=ON');$p->exec('PRAGMA busy_timeout=5000');return $p;}
function csrf():string{return $_SESSION['admin_csrf']??=bin2hex(random_bytes(32));}
function check():void{if(!hash_equals(csrf(),(string)($_POST['csrf']??'')))throw new RuntimeException('Token de seguridad inválido');}
function go(string $table='personas'):never{header('Location: ?tabla='.rawurlencode($table));exit;}
class Modelo {
 public function __construct(public PDO $db){}
 public function fields(string $t):array{return $this->db->query('PRAGMA table_info("'.$t.'")')->fetchAll();}
 public function all(string $t,string $q,int $page):array{$where='';$params=[];if($q!==''){$parts=[];foreach($this->fields($t) as $f){if($f['name']==='contrasena')continue;$parts[]='CAST("'.$f['name'].'" AS TEXT) LIKE ?';$params[]='%'.$q.'%';}$where=' WHERE '.implode(' OR ',$parts);} $count=$this->db->prepare('SELECT COUNT(*) FROM "'.$t.'"'.$where);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=$this->db->prepare('SELECT * FROM "'.$t.'"'.$where.' ORDER BY id DESC LIMIT 30 OFFSET '.(($page-1)*30));$stmt->execute($params);return [$stmt->fetchAll(),$total];}
 public function one(string $t,int $id):array{$s=$this->db->prepare('SELECT * FROM "'.$t.'" WHERE id=?');$s->execute([$id]);return $s->fetch()?:[];}
 public function save(string $t,array $data,?int $id):void{$fields=$this->fields($t);$values=[];foreach($fields as $f){$n=$f['name'];if($n==='id'||$n==='fecha')continue;if($n==='contrasena'&&trim((string)($data[$n]??''))==='')continue;if(!array_key_exists($n,$data))continue;$v=trim((string)$data[$n]);if($n==='contrasena')$v=password_hash($v,PASSWORD_DEFAULT);$values[$n]=$v;}if(!$values)throw new RuntimeException('No hay datos para guardar');if($id!==null){$sets=implode(',',array_map(fn($k)=>'"'.$k.'"=?',array_keys($values)));$s=$this->db->prepare('UPDATE "'.$t.'" SET '.$sets.' WHERE id=?');$s->execute([...array_values($values),$id]);}else{$cols=implode(',',array_map(fn($k)=>'"'.$k.'"',array_keys($values)));$s=$this->db->prepare('INSERT INTO "'.$t.'" ('.$cols.') VALUES ('.implode(',',array_fill(0,count($values),'?')).')');$s->execute(array_values($values));}}
 public function delete(string $t,int $id):void{$s=$this->db->prepare('DELETE FROM "'.$t.'" WHERE id=?');$s->execute([$id]);}
}
$error='';$logged=isset($_SESSION['scarlet_admin_id']);$table=(string)($_GET['tabla']??'personas');if(!in_array($table,TABLES,true))$table='personas';
try{$model=new Modelo(db());
 if($_SERVER['REQUEST_METHOD']==='POST'){
  check();$action=$_POST['action']??'';
  if($action==='login'){$s=$model->db->prepare('SELECT id,usuario,contrasena FROM admin_usuarios WHERE usuario=?');$s->execute([trim((string)($_POST['usuario']??''))]);$a=$s->fetch();if(!$a||!password_verify((string)($_POST['contrasena']??''),$a['contrasena']))throw new RuntimeException('Credenciales incorrectas');session_regenerate_id(true);$_SESSION['scarlet_admin_id']=$a['id'];$_SESSION['scarlet_admin_name']=$a['usuario'];go();}
  if(!$logged)throw new RuntimeException('Acceso denegado');
  if($action==='logout'){$_SESSION=[];session_destroy();header('Location: index.php');exit;}
  if($action==='save'){$id=($_POST['id']??'')!==''?(int)$_POST['id']:null;$model->save($table,$_POST,$id);go($table);}
  if($action==='delete'){$model->delete($table,(int)($_POST['id']??0));go($table);}
 }
 if($logged&&($_GET['exportar']??'')==='csv'){$q=trim((string)($_GET['q']??''));header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$table.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");$fields=array_column($model->fields($table),'name');$fields=array_values(array_diff($fields,['contrasena']));fputcsv($out,$fields);$offset=0;do{$rows=$model->all($table,$q,(int)($offset/30)+1)[0];foreach($rows as $r)fputcsv($out,array_map(fn($c)=>$r[$c]??'',$fields));$offset+=30;}while(count($rows)===30);exit;}
}catch(Throwable $e){$error=$e->getMessage();}
$logged=isset($_SESSION['scarlet_admin_id']);$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['pagina']??1));$action=$_GET['accion']??'listar';$id=(int)($_GET['id']??0);
if($logged){try{[$rows,$total]=$model->all($table,$q,$page);$fields=$model->fields($table);$record=$action==='editar'?$model->one($table,$id):[];}catch(Throwable $e){$error=$e->getMessage();$rows=[];$total=0;$fields=[];$record=[];}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ScarletRed | jocarsa red</title><link rel="stylesheet" href="css/estilo.css"><style>:root{--colorcorporativo:#b32d2e}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:15px}.toolbar input{padding:9px;border:1px solid #bbb;min-width:240px}.tabla-contenedor{overflow:auto}.tabla-contenedor td{max-width:380px;overflow-wrap:anywhere}.tabla-contenedor td.long{min-width:220px}.formulario-caja textarea{width:100%;min-height:120px;padding:10px}.formulario-caja select{width:100%;padding:9px}.aviso{padding:12px;background:#fff0f0;border-left:4px solid #b32d2e;margin:14px 0}.paginacion{display:flex;gap:12px;margin-top:20px}.badge{padding:5px 8px;background:#f2e7e7;border-radius:4px}button{cursor:pointer}.danger{color:#b32d2e;border:0;background:none}.acciones form{display:inline}.login-logo{background:#b32d2e}</style></head><body>
<?php if(!$logged):?><div class="login-pantalla"><div class="login-caja"><div class="login-logo">S</div><h1>ScarletRed</h1><p>Administración de jocarsa | red</p><?php if($error):?><div class="aviso"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="login"><label>Usuario</label><input name="usuario" type="text" required autocomplete="username"><label>Contraseña</label><input name="contrasena" type="password" required autocomplete="current-password"><button class="boton boton-primario boton-login">Acceder</button></form></div></div>
<?php else: ?><header><div class="marca"><strong>ScarletRed</strong><span>jocarsa | red · Backoffice</span></div><div class="usuario"><span><?=h($_SESSION['scarlet_admin_name']??'Admin')?></span><a href="../front/index.html">Ver red social</a><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="logout"><button class="boton">Salir</button></form></div></header><main><nav><div class="nav-titulo">Administración</div><?php foreach(TABLES as $t):?><a class="nav-link" href="?tabla=<?=h($t)?>" style="<?= $table===$t?'border-left-color:#b32d2e;background:#1d2327':''?>"><?=h(ucfirst($t))?></a><?php endforeach;?></nav><section><div class="titulo-pagina"><div><h1><?=h(ucfirst($table))?></h1><p>Gestión de registros de la red social</p></div><a class="boton boton-primario" href="?tabla=<?=h($table)?>&accion=nuevo">Añadir nuevo</a></div><?php if($error):?><div class="aviso"><?=h($error)?></div><?php endif;?>
<?php if(in_array($action,['nuevo','editar'],true)):?><div class="caja formulario-caja"><h2><?= $action==='editar'?'Editar registro':'Nuevo registro'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($record['id']??'')?>"><?php foreach($fields as $f):$n=$f['name'];if($n==='id'||$n==='fecha')continue;$v=$record[$n]??'';?><div class="campo"><label for="f_<?=h($n)?>"><?=h(ucfirst($n))?></label><?php if($n==='contenidos'||$n==='contenido'):?><textarea id="f_<?=h($n)?>" name="<?=h($n)?>" required><?=h($v)?></textarea><?php elseif($n==='contrasena'):?><input id="f_<?=h($n)?>" type="password" name="<?=h($n)?>" placeholder="<?= $action==='editar'?'Dejar vacío para mantener contraseña':'Contraseña'?>" <?= $action==='nuevo'?'required':''?>><?php elseif(str_starts_with($n,'id_')||$n==='id_post'):?><select id="f_<?=h($n)?>" name="<?=h($n)?>" required><option value="">Seleccionar...</option><?php $ref=$n==='id_post'?'publicaciones':'personas';$options=$model->db->query('SELECT * FROM "'.$ref.'" ORDER BY id DESC LIMIT 2000')->fetchAll();foreach($options as $opt):$label=$ref==='personas'?(($opt['nombre']??'').' '.($opt['apellidos']??'')):(mb_substr($opt['contenidos']??'',0,75));?><option value="<?=h($opt['id'])?>" <?= (string)$v===(string)$opt['id']?'selected':''?>>#<?=h($opt['id'])?> · <?=h($label)?></option><?php endforeach;?></select><?php else:?><input id="f_<?=h($n)?>" name="<?=h($n)?>" value="<?=h($v)?>" <?=!empty($f['notnull'])?'required':''?>><?php endif;?></div><?php endforeach;?><button class="boton boton-primario">Guardar</button> <a class="boton" href="?tabla=<?=h($table)?>">Cancelar</a></form></div>
<?php else:?><form class="toolbar" method="get"><input type="hidden" name="tabla" value="<?=h($table)?>"><input name="q" value="<?=h($q)?>" placeholder="Buscar registros"><button class="boton">Buscar</button><a class="boton" href="?tabla=<?=h($table)?>&exportar=csv&q=<?=urlencode($q)?>">Exportar CSV</a><span class="badge"><?=h($total)?> registros</span></form><div class="caja tabla-contenedor"><table><thead><tr><?php foreach($fields as $f):if($f['name']==='contrasena')continue;?><th><?=h(ucfirst($f['name']))?></th><?php endforeach;?><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($fields as $f):$n=$f['name'];if($n==='contrasena')continue;?><td class="<?=in_array($n,['contenido','contenidos'])?'long':''?>"><?=h(mb_strimwidth((string)($r[$n]??''),0,300,'…'))?></td><?php endforeach;?><td class="acciones"><a href="?tabla=<?=h($table)?>&accion=editar&id=<?=h($r['id'])?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este registro? La operación puede afectar a datos relacionados.')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="danger">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><div class="paginacion"><?php if($page>1):?><a href="?tabla=<?=h($table)?>&q=<?=urlencode($q)?>&pagina=<?=$page-1?>">← Anterior</a><?php endif;?><span>Página <?=$page?> / <?=max(1,ceil($total/30))?></span><?php if($page*30<$total):?><a href="?tabla=<?=h($table)?>&q=<?=urlencode($q)?>&pagina=<?=$page+1?>">Siguiente →</a><?php endif;?></div><?php endif;?></section></main><?php endif;?></body></html>
